import{_ as a,o,c as s,ag as t}from"./chunks/framework.DJVIMu25.js";const g=JSON.parse('{"title":"常见问题","description":"","frontmatter":{"title":"常见问题"},"headers":[],"relativePath":"zh_Hans/reference/faq.md","filePath":"zh_Hans/reference/faq.md","lastUpdated":1786543805000}'),c={name:"zh_Hans/reference/faq.md"};function d(l,e,r,n,i,m){return o(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>下面汇总了使用 JoyMart 时的常见问题与解答。点击问题展开查看答案。</p><details class="details custom-block"><summary>Q: 玩家进游戏后背包被清空了？</summary><p><strong>A:</strong> 这是设计行为——进入 JoyMart 时会保存并清空背包，离开时自动还原。如果服务器异常崩溃导致背包没还原，重启后玩家重新进一次 JoyMart 再离开即可恢复。</p></details><details class="details custom-block"><summary>Q: 双人邀请发出去对方没收到？</summary><p><strong>A:</strong> 检查 <code>config.yml</code> 的 <code>invitations.style</code> 设置（<code>json</code> / <code>actionbar</code> / <code>title</code>），以及对方是否在同一个服务器（跨服邀请需要 MySQL 模式 + BungeeCord 事件转发，本版本暂不内置跨服邀请转发）。</p></details><details class="details custom-block"><summary>Q: 商店商品点击没反应？</summary><p><strong>A:</strong> 检查 <code>tokenShop.yml</code> 缩进是否正确，以及商品的 <code>buyPermission</code> 是否被权限插件正确分配。</p></details><details class="details custom-block"><summary>Q: 上架 / 下架时光标物品消失了？</summary><p><strong>A:</strong> 早期版本在 <code>InventoryClickEvent</code> 内同步修改光标，会和客户端预测冲突导致物品&quot;卡没&quot;。本版本已将所有光标修改和 <code>build()</code> 调用包裹在 <code>Bukkit.getScheduler().runTask()</code> 中延迟到下一 tick 执行，彻底解决该问题。如果你仍遇到，请确认 jar 文件已替换为最新构建版本。</p><p>详见 <a href="./../guides/configuration#商店管理-gui">配置文件说明 - 商店管理 GUI</a> 中的&quot;上架 / 下架修复说明&quot;。</p></details><details class="details custom-block"><summary>Q: 彩票 / 抽奖机的奖项怎么改？</summary><p><strong>A:</strong> 管理员执行 <code>/gba games</code> → 选择对应游戏 → 点击 <strong>奖项池</strong> 按钮，在 GUI 中可视化增删奖项、调整权重和奖励即可，保存后自动写入对应游戏 <code>config.yml</code>，无需手改文件。</p><p>奖项池的配置文件格式见 <a href="./../guides/configuration#奖项池配置">配置文件说明 - 彩票 / 抽奖机的奖项池配置</a>。</p></details><details class="details custom-block"><summary>Q: 迷宫太简单 / 太难？</summary><p><strong>A:</strong> 迷宫大小写死为 9×9（递归回溯法保证唯一通路）。如需调整，可修改 <code>MazeSession.java</code> 中的 <code>n</code> 常量并重新构建。</p></details><details class="details custom-block"><summary>Q: 如何添加自己的语言？</summary><p><strong>A:</strong> 复制 <code>plugins/JoyMart/language/language_en.yml</code> 为 <code>language_xx.yml</code>，翻译所有键值，然后在 <code>config.yml</code> 设置 <code>language.default: xx</code>。游戏专用语言文件位于 <code>language/game_&lt;游戏名&gt;/language_xx.yml</code>，同样复制翻译即可。</p></details><details class="details custom-block"><summary>Q: 设置了中文但游戏内还是英文？</summary><p><strong>A:</strong> 确保 <code>config.yml</code> 中 <code>language.default: zh</code>，然后执行 <code>/gba reload</code>。插件会自动将 <code>language_zh.yml</code> 和各游戏的 <code>language_zh.yml</code> 复制到 <code>plugins/JoyMart/language/</code> 目录。</p></details>',10)])])}const p=a(c,[["render",d]]);export{g as __pageData,p as default};
